blind.equal:
def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Equal shares of the whole reservoir."""
    p = prev_contrib.shape[1]
    return np.repeat(pool[:, None] / p, p, axis=1)

seeded.equal:
def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Equal shares of the whole reservoir."""
    p = prev_contrib.shape[1]
    return np.repeat(pool[:, None] / p, p, axis=1)

blind_shares.equal:
def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Equal weights."""
    return np.ones_like(prev_contrib)

blind_shares.proportional:
def allocate(pool, prev_offer, prev_contrib, t, mem, cap, growth):
    """Weights proportional to last round's returns."""
    return prev_contrib.copy()
